```c
#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int data;
    struct node *next;
} Node;

int main() {
    Node *head = NULL, *p;
    // 创建链表 1 -> 2 -> 3
    for(int i = 3; i >= 1; i--) {
        p = (Node*)malloc(sizeof(Node));
        p->data = i;
        p->next = head;
        head = p;
    }

    // 模拟蛇移动：删除尾节点
    Node *temp = head;
    while(temp->next->next != NULL) {
        temp = temp->next;
    }
    free(temp->next);
    temp->next = NULL;

    // 打印链表
    p = head;
    while(p != NULL) {
        printf("%d ", p->data);
        p = p->next;
    }
    return 0;
}
```

